#!/usr/bin/env node
/**
 * Keep the deploy tree self-contained by vendoring the two compiled docbuild
 * modules the edit endpoint needs into `netlify/lib/`, and prove the committed
 * copies are byte-for-byte what the canonical build emits.
 *
 * `netlify/functions/edit.mjs` needs P1-D's `scanBlocks` and P2-D's `toMd`/
 * `toHtml`. Importing them from `templates/docbuild/dist/` does not work:
 * `dist/` is gitignored, so the import resolves only on a machine that happens
 * to have built docbuild, and the P4-S connect tool copies only `netlify/`,
 * `netlify.toml`, `package.json` and `package-lock.json` into a connected
 * site, so the module is absent from every deploy bundle (#117).
 *
 * The vendored copies are generated, never hand-written. That is the property
 * that makes them safe: `templates/docbuild/src` stays the single source of
 * both algorithms, and a source change that is not re-vendored fails this
 * check by name instead of drifting silently. It is the same contract
 * `templates/check-dist` holds over committed document output, which already
 * carries this exact compiled `anchor-core.js` inlined into every page.
 *
 * Vendoring the two modules fixes one import. The last section of this check
 * fixes the class: every relative specifier anywhere under `netlify/` must
 * resolve to a file that is itself under `netlify/`. That is the whole meaning
 * of a self-contained deploy tree, and it is the assertion that makes the
 * original defect unrepeatable rather than merely repaired.
 *
 * Usage:
 *
 *   node scripts/vendor-netlify-lib.mjs            # verify, the CI mode
 *   node scripts/vendor-netlify-lib.mjs --write    # regenerate
 *
 * Both modes need the canonical build present; run
 * `npm --prefix templates/docbuild run build` first. Output contract: exactly
 * one `PASS`/`WROTE` line on stdout and exit 0, or `FAIL vendored netlify
 * modules:` lines on stderr and exit 1 (exit 2 for an invalid command line).
 * `--write` renders both copies before writing either, so a failure never
 * leaves the tree half vendored.
 */

import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, relative, resolve, sep } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

/** The repository root, derived from this file's own location. */
const ROOT = dirname(dirname(fileURLToPath(import.meta.url)));

/** The deploy tree: exactly what the P4-S connect tool copies, minus config. */
const DEPLOY_ROOT = join(ROOT, "netlify");

/** Source extensions inside the deploy tree that carry module specifiers. */
const DEPLOY_EXTENSIONS = [".mjs", ".js", ".ts"];

/** The TypeScript compiler the repository already pins for the builder. */
const TYPESCRIPT_HOST = join(ROOT, "templates", "docbuild", "package.json");

/**
 * Every vendored module, as (compiled source, committed copy). `source` is
 * build output and `target` is tracked; nothing else in `dist/` is vendored,
 * because nothing else is imported by a function. `exports` is what the deploy
 * tree actually consumes.
 *
 * The paths are literal forward-slash strings, not `join()` results, because
 * `origin` is written into the generated bytes: composing it from the host
 * separator would make the committed file differ between a Windows checkout
 * and Linux CI, and the whole point of these entries is bytes that do not
 * depend on where they were produced. `join(ROOT, ...)` at the point of use
 * accepts forward slashes on every platform.
 */
const VENDORED = [
  {
    source: "templates/docbuild/dist/anchor-core.js",
    origin: "templates/docbuild/src/anchor-core.ts",
    target: "netlify/lib/anchor-core.mjs",
    exports: ["BLOCK", "norm", "scanBlocks"],
  },
  {
    source: "templates/docbuild/dist/inline_md.js",
    origin: "templates/docbuild/src/inline_md.ts",
    target: "netlify/lib/inline-md.mjs",
    exports: ["toHtml", "toMd"],
  },
];

/**
 * The trailing tsc source-map reference, which has no map beside the copy.
 * Anchored to end of file: an identical line inside a string literal is source,
 * not a footer, and stripping it would ship bytes that are not what compiled.
 */
const SOURCE_MAP_COMMENT = /\n?\/\/# sourceMappingURL=[^\n]*\n?$/;

/** The exact banner every vendored copy carries, ahead of the compiled bytes. */
function banner(entry) {
  return [
    "// Generated file. Do not edit.",
    "//",
    `// The compiled output of \`${entry.origin}\`, vendored`,
    "// here so the deploy tree the P4-S connect tool copies is self-contained.",
    "// Editing this file by hand cannot change what the builder or the browser",
    "// runs; edit that source instead.",
    "//",
    "// Regenerate with `node scripts/vendor-netlify-lib.mjs --write`. CI runs",
    "// `node scripts/vendor-netlify-lib.mjs` and fails on any drift.",
    "",
    "",
  ].join("\n");
}

/** Render the exact bytes the committed copy must hold. */
function render(entry) {
  const path = join(ROOT, entry.source);
  let compiled;
  let built;
  try {
    compiled = readFileSync(path, "utf8");
    built = statSync(path).mtimeMs;
  } catch {
    return {
      error:
        `${entry.source} is missing; run \`npm --prefix templates/docbuild run build\``,
    };
  }
  // CI cannot hit this — `dist/` is gitignored, so the typecheck step's
  // `npm ci` prepare build always emits it fresh. A working copy can, and
  // comparing a committed file to yesterday's compiler output is a PASS that
  // means nothing. `templates/build` guards itself the same way.
  if (statSync(join(ROOT, entry.origin)).mtimeMs > built) {
    return {
      error:
        `${entry.source} is older than ${entry.origin}; run ` +
        "`npm --prefix templates/docbuild run build`",
    };
  }
  // The source map is emitted beside `dist/`, which is not vendored, so a
  // reference to it here would dangle in every deploy.
  const body = compiled.replace(SOURCE_MAP_COMMENT, "");
  if (body.trim() === "") return { error: `${entry.source} is empty` };
  return { text: `${banner(entry)}${body.replace(/\n*$/, "\n")}` };
}

/**
 * Load the committed copy and require the names the deploy tree imports.
 *
 * Equal bytes are only worth something if those bytes are a usable module.
 * This is what catches a build that emitted a valid but degenerate file, and a
 * compiled source that grew a relative import: tsc under `module: NodeNext`
 * would emit `from "./anchor-core.js"`, which does not exist beside a vendored
 * `.mjs`, so the copy would fail to load here rather than in a deploy. Both
 * modules are pure and import-free, so loading them costs nothing.
 */
async function requireExports(entry) {
  let loaded;
  try {
    loaded = await import(pathToFileURL(join(ROOT, entry.target)).href);
  } catch {
    return `${entry.target} does not load`;
  }
  const missing = entry.exports.filter((name) => loaded[name] === undefined);
  if (missing.length > 0) {
    return `${entry.target} does not export ${missing.join(", ")}`;
  }
  return null;
}

// ---------------------------------------------------------------------------
// The deploy tree is self-contained
// ---------------------------------------------------------------------------

/** Every source file under `netlify/`, in a stable order. */
function deploySources(directory = DEPLOY_ROOT) {
  const found = [];
  for (const name of readdirSync(directory).sort()) {
    const path = join(directory, name);
    if (statSync(path).isDirectory()) found.push(...deploySources(path));
    else if (DEPLOY_EXTENSIONS.some((extension) => name.endsWith(extension))) found.push(path);
  }
  return found;
}

/**
 * Collect every module specifier in one file, using the pinned TypeScript
 * parser rather than a regular expression.
 *
 * A regex over source text cannot tell an `import` in code from the word
 * "imports" in a comment, and this check's whole value is that a failure means
 * something. `edit.mjs` documents its own imports in prose directly above
 * them, so a text scan would fail closed on correct code the first time it ran.
 */
function specifiersIn(ts, path) {
  const source = ts.createSourceFile(
    path,
    readFileSync(path, "utf8"),
    ts.ScriptTarget.ES2022,
    /* setParentNodes */ false,
    path.endsWith(".ts") ? ts.ScriptKind.TS : ts.ScriptKind.JS,
  );
  if (source.parseDiagnostics.length > 0) return { error: "does not parse" };

  const specifiers = [];
  const visit = (node) => {
    if (
      (ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) &&
      node.moduleSpecifier !== undefined &&
      ts.isStringLiteral(node.moduleSpecifier)
    ) {
      specifiers.push(node.moduleSpecifier.text);
    }
    if (
      ts.isCallExpression(node) &&
      node.expression.kind === ts.SyntaxKind.ImportKeyword &&
      node.arguments.length > 0 &&
      ts.isStringLiteralLike(node.arguments[0])
    ) {
      specifiers.push(node.arguments[0].text);
    }
    ts.forEachChild(node, visit);
  };
  ts.forEachChild(source, visit);
  return { specifiers };
}

/**
 * Require every relative import under `netlify/` to land under `netlify/`.
 *
 * Bare specifiers are fine: they are npm packages, and `package.json` plus
 * `package-lock.json` travel with the deploy tree. `node:` builtins are fine.
 * A relative specifier is the only kind that can reach code the deploy does
 * not carry, which is exactly what #117 was.
 */
function requireSelfContained() {
  let ts;
  try {
    ts = createRequire(pathToFileURL(TYPESCRIPT_HOST))("typescript");
  } catch {
    return ["the pinned TypeScript compiler is unavailable"];
  }

  const failures = [];
  for (const path of deploySources()) {
    const name = relative(ROOT, path).split(sep).join("/");
    const read = specifiersIn(ts, path);
    if (read.error !== undefined) {
      failures.push(`${name} ${read.error}`);
      continue;
    }
    for (const specifier of read.specifiers) {
      if (!specifier.startsWith(".") && !specifier.startsWith("/")) continue;
      const target = resolve(dirname(path), specifier);
      const inside = target === DEPLOY_ROOT || target.startsWith(DEPLOY_ROOT + sep);
      if (!inside) {
        failures.push(`${name} imports "${specifier}", which is outside the deploy tree`);
      } else if (!existsSync(target)) {
        failures.push(`${name} imports "${specifier}", which does not exist`);
      }
    }
  }
  return failures;
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

async function main(argv) {
  let write = false;
  if (argv.length === 1 && argv[0] === "--write") write = true;
  else if (argv.length !== 0) {
    process.stderr.write("FAIL vendored netlify modules: invalid arguments\n");
    return 2;
  }

  const failures = [];
  // Drift is the only failure the regenerate hint answers. A missing build
  // needs `npm --prefix templates/docbuild run build` instead, and printing
  // both would send half of the readers to the wrong command.
  let drifted = false;

  // Render every entry before touching the tree. A `--write` that regenerated
  // one file and then failed on the other would leave the repository half
  // vendored, which is a worse state than the one it was asked to fix.
  const rendered = [];
  for (const entry of VENDORED) {
    const result = render(entry);
    if (result.error !== undefined) failures.push(result.error);
    else rendered.push({ entry, text: result.text });
  }

  if (failures.length === 0 && write) {
    for (const { entry, text } of rendered) {
      try {
        writeFileSync(join(ROOT, entry.target), text);
      } catch {
        failures.push(`${entry.target} could not be written`);
      }
    }
  }

  if (failures.length === 0 && !write) {
    for (const { entry, text } of rendered) {
      let committed;
      try {
        committed = readFileSync(join(ROOT, entry.target), "utf8");
      } catch {
        failures.push(`${entry.target} is missing`);
        drifted = true;
        continue;
      }
      if (committed !== text) {
        failures.push(`${entry.target} is not what ${entry.source} compiles to`);
        drifted = true;
      }
    }
  }

  // Bytes that match are only worth something if they are a usable module.
  if (failures.length === 0) {
    for (const { entry } of rendered) {
      const reason = await requireExports(entry);
      if (reason !== null) failures.push(reason);
    }
  }

  // Vendoring is the repair; this is the invariant it was repairing towards.
  // It runs in both modes, because it is a property of the tree rather than of
  // anything this command just wrote.
  failures.push(...requireSelfContained());

  if (failures.length > 0) {
    for (const failure of failures) {
      process.stderr.write(`FAIL vendored netlify modules: ${failure}\n`);
    }
    if (drifted) {
      process.stderr.write(
        "If the source change is intended, run `node scripts/vendor-netlify-lib.mjs --write`" +
          " and commit the result.\n",
      );
    }
    return 1;
  }

  const names = VENDORED.map((entry) => entry.target).join(", ");
  const verb = write ? "WROTE" : "PASS";
  process.stdout.write(
    `${verb} vendored netlify modules: ${names}; the deploy tree is self-contained\n`,
  );
  return 0;
}

process.exitCode = await main(process.argv.slice(2));
